 ('748bf67a-cfb4-5da8-ae2f-ffedc63d7d53', 'tts/openai/748bf67a-cfb4-5da8-ae2f-ffedc63d7d53.mp3', 'Guia-nos, Senhor, durante o dia, e guarda-nos enquanto dormimos. Que em nosso despertar vigiemos com Cristo e, no silêncio da noite, descansemos em paz.', 'congregation', 'line', 'openai', 'cedar', 'gpt-4o-mini-tts', 1.0, 5.455, 152, 'pt-BR', 'difftest', NULL, now(), now()),
