 ('c3486f04-9d2f-5865-af64-06343d1e17d9', 'tts/openai/c3486f04-9d2f-5865-af64-06343d1e17d9.mp3', 'Na minha angústia clamei ao Senhor; e o Senhor me respondeu, dando-me ampla liberdade.', 'reading_text', 'line', 'openai', 'cedar', 'gpt-4o-mini-tts', 1.0, 4.595, 86, 'pt-BR', 'difftest', NULL, now(), now()),
