 ('d536baae-790a-51ec-82f6-642f5c5d6c9a', 'tts/openai/d536baae-790a-51ec-82f6-642f5c5d6c9a.mp3', 'Then Job answered the Lord, and said,', 'reading_text', 'line', 'openai', 'cedar', 'gpt-4o-mini-tts', 1.0, 2.171, 37, 'en', 'difftest', NULL, now(), now()),
 ('eb6029f7-8986-5c34-bb07-2dbe2c87218a', 'tts/openai/eb6029f7-8986-5c34-bb07-2dbe2c87218a.mp3', 'I know that thou canst do every thing, and that no thought can be withholden from thee. no thought can be: or, no thought of thine can be hindered', 'reading_text', 'line', 'openai', 'cedar', 'gpt-4o-mini-tts', 1.0, 1.341, 146, 'en', 'difftest', NULL, now(), now()),
 ('e841483d-8f8c-594e-8bd7-c553a28665be', 'tts/openai/e841483d-8f8c-594e-8bd7-c553a28665be.mp3', 'Who is he that hideth counsel without knowledge? therefore have I uttered that I understood not; things too wonderful for me, which I knew not.', 'reading_text', 'line', 'openai', 'cedar', 'gpt-4o-mini-tts', 1.0, 7.178, 143, 'en', 'difftest', NULL, now(), now()),
