 ('09193fd0-5267-5544-823d-063f0c2db507', 'tts/openai/09193fd0-5267-5544-823d-063f0c2db507.mp3', 'And when they had lifted up their eyes, they saw no man, save Jesus only.', 'reading_text', 'line', 'openai', 'cedar', 'gpt-4o-mini-tts', 1.0, 1.947, 73, 'en', 'difftest', NULL, now(), now()),
 ('d3ae21e7-a813-573b-8504-9fb705694578', 'tts/openai/d3ae21e7-a813-573b-8504-9fb705694578.mp3', 'And as they came down from the mountain, Jesus charged them, saying, Tell the vision to no man, until the Son of man be risen again from the dead.', 'reading_text', 'line', 'openai', 'cedar', 'gpt-4o-mini-tts', 1.0, 2.841, 146, 'en', 'difftest', NULL, now(), now()),
