 ('7517069f-6fb9-5dc6-8547-837a85017aba', 'tts/openai/7517069f-6fb9-5dc6-8547-837a85017aba.mp3', 'And I brought him to thy disciples, and they could not cure him.', 'reading_text', 'line', 'openai', 'cedar', 'gpt-4o-mini-tts', 1.0, 8.498, 64, 'en', 'difftest', NULL, now(), now()),
