 ('43975177-3a30-5694-ac79-3c096dfddac7', 'tts/openai/43975177-3a30-5694-ac79-3c096dfddac7.mp3', 'OUR Father, which art in heaven, Hallowed be thy Name. Thy kingdom come. Thy will be done in earth, As it is in heaven. Give us this day our daily bread. And forgive us our trespasses, As we forgive them that trespass against us. And lead us not into temptation, But deliver us from evil.', 'text', 'line', 'openai', 'cedar', 'gpt-4o-mini-tts', 1.0, 6.059, 288, 'en', 'difftest', NULL, now(), now()),
